"""The simulated clock. Use it instead of Python's time module. Do not edit this file.

    import clock
    clock.now()                    # the current simulated time, in ms
    clock.set_timer(delay_ms, fn)  # call fn() after delay_ms; returns a timer
"""

import inspect

_sim = None  # set by sim.py before your code runs


class Timer:
    def __init__(self):
        self.cancelled = False

    def cancel(self):
        """Stop the timer, so fn() is not called."""
        self.cancelled = True


def now():
    """The current simulated time, in ms."""
    return _sim.now


def set_timer(delay_ms, fn):
    """Call fn() after delay_ms. Returns a timer with a cancel() method."""
    if not isinstance(delay_ms, (int, float)) or isinstance(delay_ms, bool) or not 0 <= delay_ms < float("inf"):
        raise ValueError("clock.set_timer needs a delay in ms that is a number of at least 0, not %r" % (delay_ms,))
    if not callable(fn):
        raise TypeError("clock.set_timer needs a function to call, not %s" % type(fn).__name__)
    try:
        inspect.signature(fn).bind()
    except TypeError:
        raise TypeError("clock.set_timer calls its function with no arguments, but %s needs some"
                        % getattr(fn, "__qualname__", "that function")) from None
    except ValueError:
        pass  # some built-in functions do not say what arguments they take
    timer = Timer()
    _sim.at(_sim.now + delay_ms, lambda: timer.cancelled or fn())
    return timer
